from urllib.parse import quote_plus


def news(q):
    return f"https://news.google.com/rss/search?q={quote_plus(q)}&hl=en-IN&gl=IN&ceid=IN:en"


def P(name, role, industry, size, pain, goals, obj, channels, triggers):
    return dict(name=name, role=role, industry=industry, company_size=size, pain_points=pain, goals=goals, objections=obj, channels=channels, buying_triggers=triggers)


